export const sortByProperty = <T>(array: T[], property: keyof T, ascending = true): T[] => {
  return [...array].sort((a, b) => {
    if (a[property] < b[property]) return ascending ? -1 : 1;
    if (a[property] > b[property]) return ascending ? 1 : -1;
    return 0;
  });
};

export const filterByProperty = <T>(array: T[], property: keyof T, value: any): T[] => {
  return array.filter((item) => item[property] === value);
};

export const groupByProperty = <T>(array: T[], property: keyof T): Record<string, T[]> => {
  return array.reduce((acc, item) => {
    const key = String(item[property]);
    if (!acc[key]) {
      acc[key] = [];
    }
    acc[key].push(item);
    return acc;
  }, {} as Record<string, T[]>);
};

