  const [isEditing, setIsEditing] = useState(false);

  const handleChange = (field: keyof UserProfile, value: string | string[]) => {
    setProfile(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const toggleEdit = () => {
    setIsEditing(!isEditing);
  };

  const saveProfile = () => {
    // In a real app, you would save to an API here
    setIsEditing(false);
  };

  return {
    profile,
    isEditing,
    handleChange,
    toggleEdit,
    saveProfile
  };
};

