import React, { useState, useEffect } from 'react';
import { BarChart, PieChart, DataTable, DateRangePicker, Heatmap, TrendIndicator, Map, DataSummaryCards, ExportButton, Filters } from '../../components/AnalyticsComponents';
import { fetchAnalyticsData } from '../../services/analyticsService';
import './analytics.css';

type AnalyticsData = {
  date: string;
  visitors: number;
  pageViews: number;
  bounceRate: number;
  conversions: number;
  region: string;
  device: string;
  source: string;
};

type DateRange = {
  start: Date;
  end: Date;
};

export const AnalyticsPage: React.FC = () => {
  const [data, setData] = useState<AnalyticsData[]>([]);
  const [filteredData, setFilteredData] = useState<AnalyticsData[]>([]);
  const [dateRange, setDateRange] = useState<DateRange>({
    start: new Date(new Date().setDate(new Date().getDate() - 30)),
    end: new Date(),
  });
  const [filters, setFilters] = useState({
    region: 'all',
    device: 'all',
    source: 'all',
  });
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const response = await fetchAnalyticsData(dateRange);
        setData(response);
        applyFilters(response, filters);
      } catch (error) {
        console.error('Error fetching analytics data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, [dateRange]);

  const applyFilters = (dataToFilter: AnalyticsData[], currentFilters: any) => {
    let result = [...dataToFilter];
    if (currentFilters.region !== 'all') {
      result = result.filter(item => item.region === currentFilters.region);
    }
    if (currentFilters.device !== 'all') {
      result = result.filter(item => item.device === currentFilters.device);
    }
    if (currentFilters.source !== 'all') {
      result = result.filter(item => item.source === currentFilters.source);
    }
    setFilteredData(result);
  };

  const handleDateChange = (newDateRange: DateRange) => {
    setDateRange(newDateRange);
  };

  const handleFilterChange = (name: string, value: string) => {
    const newFilters = { ...filters, [name]: value };
    setFilters(newFilters);
    applyFilters(data, newFilters);
  };

  const handleExport = () => {
    // Export logic would go here
    console.log('Exporting data:', filteredData);
  };

  if (isLoading) {
    return <div className="loading">Loading analytics data...</div>;
  }

  return (
    <div className="analytics-container">
      <h1>Website Analytics</h1>

      <div className="controls-row">
        <DateRangePicker 
          initialRange={dateRange} 
          onChange={handleDateChange} 
        />
        <Filters 
          filters={filters} 
          onChange={handleFilterChange} 
          options={{
            region: ['all', 'North America', 'Europe', 'Asia', 'South America'],
            device: ['all', 'Desktop', 'Mobile', 'Tablet'],
            source: ['all', 'Organic', 'Direct', 'Referral', 'Social', 'Email']
          }} 
        />
        <ExportButton onClick={handleExport} />
      </div>

      <div className="summary-row">
        <DataSummaryCards 
          data={[
            { title: 'Total Visitors', value: filteredData.reduce((sum, item) => sum + item.visitors, 0) },
            { title: 'Page Views', value: filteredData.reduce((sum, item) => sum + item.pageViews, 0) },
            { title: 'Avg. Bounce Rate', value: filteredData.reduce((sum, item) => sum + item.bounceRate, 0) / filteredData.length },
            { title: 'Conversions', value: filteredData.reduce((sum, item) => sum + item.conversions, 0) }
          ]} 
        />
      </div>

      <div className="chart-row">
        <div className="chart-container">
          <h2>Visitor Trends</h2>
          <BarChart 
            data={filteredData.map(item => ({
              date: item.date,
              visitors: item.visitors,
              pageViews: item.pageViews
            }))} 
            keys={['visitors', 'pageViews']} 
          />
        </div>

        <div className="chart-container">
          <h2>Traffic Sources</h2>
          <PieChart 
            data={[
              { name: 'Organic', value: filteredData.filter(item => item.source === 'Organic').length },
              { name: 'Direct', value: filteredData.filter(item => item.source === 'Direct').length },
              { name: 'Referral', value: filteredData.filter(item => item.source === 'Referral').length },
              { name: 'Social', value: filteredData.filter(item => item.source === 'Social').length },
              { name: 'Email', value: filteredData.filter(item => item.source === 'Email').length }
            ]} 
          />
        </div>
      </div>

      <div className="map-row">
        <h2>Geographic Distribution</h2>
        <Map 
          data={filteredData.reduce((acc, item) => {
            if (!acc[item.region]) acc[item.region] = 0;
            acc[item.region] += item.visitors;
            return acc;
          }, {} as Record<string, number>)} 
        />
      </div>

      <div className="heatmap-row">
        <h2>Activity Heatmap</h2>
        <Heatmap 
          data={filteredData.map(item => ({
            date: item.date,
            hour: Math.floor(Math.random() * 24), // Mock hour for demo
            value: item.visitors
          }))} 
        />
      </div>

      <div className="table-row">
        <h2>Detailed Data</h2>
        <DataTable 
          columns={[
            { header: 'Date', accessor: 'date' },
            { header: 'Visitors', accessor: 'visitors' },
            { header: 'Page Views', accessor: 'pageViews' },
            { header: 'Bounce Rate', accessor: 'bounceRate', format: (value: number) => `${value.toFixed(1)}%` },
            { header: 'Conversions', accessor: 'conversions' },
            { header: 'Region', accessor: 'region' },
            { header: 'Device', accessor: 'device' },
            { header: 'Source', accessor: 'source' }
          ]} 
          data={filteredData} 
        />
      </div>

      <div className="trend-row">
        <TrendIndicator 
          currentValue={filteredData.reduce((sum, item) => sum + item.visitors, 0)}
          previousValue={data.reduce((sum, item) => sum + item.visitors, 0) - filteredData.reduce((sum, item) => sum + item.visitors, 0)}
          label="Visitor Trend"
        />
      </div>
    </div>
  );
};

