import { useState, useEffect } from 'react';
import { fetchDashboardData } from '../services/dashboardService';

interface DashboardData {
  metrics: {
    totalUsers: number;
    activeProjects: number;
    tasksCompleted: number;
    revenue: number;
  };
  chartData: {
    labels: string[];
    datasets: {
      label: string;
      data: number[];
      borderColor: string;
      backgroundColor: string;
    }[];
  };
  notifications: {
    id: number;
    title: string;
    message: string;
    timestamp: string;
    isRead: boolean;
  }[];
  activities: {
    id: number;
    user: string;
    action: string;
    timestamp: string;
    avatar: string;
  }[];
  progress: {
    current: number;
    target: number;
    label: string;
  };
  quickLinks: {
    title: string;
    url: string;
    icon: string;
  }[];
  weather: {
    temperature: number;
    condition: string;
    icon: string;
    location: string;
  };
  recentFiles: {
    name: string;
    type: string;
    size: string;
    modified: string;
    owner: string;
  }[];
  announcements: {
    id: number;
    title: string;
    content: string;
    date: string;
  }[];
  teamMembers: {
    id: number;
    name: string;
    role: string;
    avatar: string;
    status: 'online' | 'offline' | 'busy';
  }[];
}

export const useDashboardData = () => {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadData = async () => {
      try {
        const response = await fetchDashboardData();
        setData(response);
      } catch (err) {
        setError('Failed to load dashboard data');
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  return { data, loading, error };
};

