import React, { useState } from 'react';

interface Notification {
  id: number;
  title: string;
  message: string;
  timestamp: string;
  isRead: boolean;
}

interface NotificationsListProps {
  notifications: Notification[];
}

const NotificationsList: React.FC<NotificationsListProps> = ({ notifications }) => {
  const [notifs, setNotifs] = useState<Notification[]>(notifications);

  const markAsRead = (id: number) => {
    setNotifs(notifs.map(notif => 
      notif.id === id ? { ...notif, isRead: true } : notif
    ));
  };

  const markAllAsRead = () => {
    setNotifs(notifs.map(notif => ({ ...notif, isRead: true }));
  };

  return (
    <div className="notifications-list">
      <div className="notifications-header">
        <h3>Notifications</h3>
        <button onClick={markAllAsRead}>Mark all as read</button>
      </div>

      <ul>
        {notifs.map(notification => (
          <li key={notification.id} className={notification.isRead ? 'read' : 'unread'}>
            <div className="notification-content">
              <h4>{notification.title}</h4>
              <p>{notification.message}</p>
              <span className="timestamp">{notification.timestamp}</span>
            </div>
            {!notification.isRead && (
              <button onClick={() => markAsRead(notification.id)}>Mark as read</button>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default NotificationsList;

