src/pages/dashboard/components/Announcem:
import React, { useState } from 'react';

interface Announcement {
  id: number;
  title: string;
  content: string;
  date: string;
}

interface AnnouncementsBannerProps {
  announcements: Announcement[];
}

const AnnouncementsBanner: React.FC<AnnouncementsBannerProps> = ({ announcements }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  const nextAnnouncement = () => {
    setCurrentIndex((prevIndex) => 
      prevIndex === announcements.length - 1 ? 0 : prevIndex + 1
    );
  };

  const prevAnnouncement = () => {
    setCurrentIndex((prevIndex) => 
      prevIndex === 0 ? announcements.length - 1 : prevIndex - 1
    );
  };

  React.useEffect(() => {
    if (announcements.length > 1 && !isPaused) {
      const timer = setInterval(nextAnnouncement, 5000);
      return () => clearInterval(timer);
    }
  }, [announcements.length, isPaused]);

  if (announcements.length === 0) return null;

  const currentAnnouncement = announcements[currentIndex];

  return (
    <div 
      className="announcements-banner"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div className="announcement-content">
        <h3>{currentAnnouncement.title}</h3>
        <p>{currentAnnouncement.content}</p>
        <span className="date">{currentAnnouncement.date}</span>
      </div>

      {announcements.length > 1 && (
        <div className="announcement-controls">
          <button onClick={prevAnnouncement}>‹</button>
          <span>{currentIndex + 1} / {announcements.length}</span>
          <button onClick={nextAnnouncement}>›</button>
        </div>
      )}
    </div>
  );
};

export default AnnouncementsBanner;

