import React, { useState } from 'react';
import { TextField, Button, Stack, Typography } from '@mui/material';

type ProfileData = {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  bio: string;
};

export const EditableProfileForm: React.FC<{ initialData: ProfileData }> = ({ initialData }) => {
  const [profileData, setProfileData] = useState<ProfileData>(initialData);
  const [isEditing, setIsEditing] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setProfileData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, you would save to API here
    setIsEditing(false);
  };

  return (
    <Stack component="form" onSubmit={handleSubmit} spacing={2} sx={{ p: 3 }}>
      <Typography variant="h6">Profile Information</Typography>

      <TextField
        label="First Name"
        name="firstName"
        value={profileData.firstName}
        onChange={handleChange}
        disabled={!isEditing}
        fullWidth
      />
      <TextField
        label="Last Name"
        name="lastName"
        value={profileData.lastName}
        onChange={handleChange}
        disabled={!isEditing}
        fullWidth
      />
      <TextField
        label="Email"
        name="email"
        type="email"
        value={profileData.email}
        onChange={handleChange}
        disabled={!isEditing}
        fullWidth
      />
      <TextField
        label="Phone"
        name="phone"
        value={profileData.phone}
        onChange={handleChange}
        disabled={!isEditing}
        fullWidth
      />
      <TextField
        label="Bio"
        name="bio"
        value={profileData.bio}
        onChange={handleChange}
        disabled={!isEditing}
        multiline
        rows={4}
        fullWidth
      />

      {isEditing ? (
        <Stack direction="row" spacing={2}>
          <Button type="submit" variant="contained">Save</Button>
          <Button variant="outlined" onClick={() => setIsEditing(false)}>Cancel</Button>
        </Stack>
      ) : (
        <Button variant="contained" onClick={() => setIsEditing(true)}>Edit Profile</Button>
      )}
    </Stack>
  );
};

