import { mockAnalyticsData } from '../mocks/analyticsData';

type AnalyticsData = {
  date: string;
  visitors: number;
  pageViews: number;
  bounceRate: number;
  conversions: number;
  region: string;
  device: string;
  source: string;
};

type DateRange = {
  start: Date;
  end: Date;
};

export const fetchAnalyticsData = async (dateRange: DateRange): Promise<AnalyticsData[]> => {
  // In a real app, this would be an API call
  // For now, we'll filter the mock data by date range

  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 800));

  const startTime = dateRange.start.getTime();
  const endTime = dateRange.end.getTime();

  return mockAnalyticsData.filter(item => {
    const itemTime = new Date(item.date).getTime();
    return itemTime >= startTime && itemTime <= endTime;
  });
};

