export const formatChartData = (rawData: Record<string, unknown>[]) => {
  return rawData.map(item => ({
    name: item.date,
    value: item.count,
  }));
};

export const calculateMetrics = (data: Record<string, unknown>[]) => {
  const total = data.reduce((sum, item) => sum + (item.value as number), 0);
  const average = total / data.length;
  const max = Math.max(...data.map(item => item.value as number));
  const min = Math.min(...data.map(item => item.value as number));

  return { total, average, max, min };
};

export const filterDataByDateRange = (
  data: Record<string, unknown>[],
  startDate: string,
  endDate: string
) => {
  return data.filter(item => {
    const itemDate = new Date(item.date as string);
    return (
      itemDate >= new Date(startDate) &&
      itemDate <= new Date(endDate)
    );
  });
};

