export const sortProjectsByDeadline = (projects: Record<string, unknown>[]) => {
  return [...projects].sort((a, b) => {
    return new Date(a.deadline as string).getTime() - new Date(b.deadline as string).getTime();
  });
};

export const calculateProjectProgress = (tasks: Record<string, unknown>[]) => {
  if (!tasks.length) return 0;
  const completedTasks = tasks.filter(task => task.status === 'completed');
  return Math.round((completedTasks.length / tasks.length) * 100);
};

export const groupTasksByStatus = (tasks: Record<string, unknown>[]) => {
  return tasks.reduce((acc, task) => {
    const status = task.status as string;
    if (!acc[status]) {
      acc[status] = [];
    }
    acc[status].push(task);
    return acc;
  }, {} as Record<string, unknown[]>);
};

