export const formatUserFullName = (user: Record<string, unknown>) => {
  return `${user.firstName} ${user.lastName}`.trim();
};

export const getUserInitials = (user: Record<string, unknown>) => {
  const firstName = user.firstName as string;
  const lastName = user.lastName as string;
  return `${firstName.charAt(0)}${lastName.charAt(0)}`.toUpperCase();
};

export const filterUsersByRole = (users: Record<string, unknown>[], role: string) => {
  return users.filter(user => user.role === role);
};

export const sortUsersByName = (users: Record<string, unknown>[]) => {
  return [...users].sort((a, b) => {
    const nameA = formatUserFullName(a).toLowerCase();
    const nameB = formatUserFullName(b).toLowerCase();
    return nameA.localeCompare(nameB);
  });
};
